  ('4920036d-606c-5b39-9817-1aa44ffd7d5d', '080920e1-dfcc-555f-94e8-0864285aa5e7', 2, 'Practice', 'practice', 'draft'),
  ('e3fe70f4-12ff-5f57-ac67-1618788a7d15', '080920e1-dfcc-555f-94e8-0864285aa5e7', 3, 'Practice', 'practice', 'draft'),
